-- ==========================================================================
-- SQL Seed Records for 'LCCL Annual Fundraiser Gala 2026' (Event ID 1)
-- Total Records: 1 Event | 4 Table Types | 50 Tables | 112 Bookings
-- Prefix: Uses 'wp_' by default. Replace 'wp_' with your DB prefix if different.
-- ==========================================================================

SET FOREIGN_KEY_CHECKS = 0;

-- --------------------------------------------------------------------------
-- Step 0: Pre-Cleanup
-- If this event (or a similar gala event) already exists, delete all associated
-- bookings, seat blocks, tables, table types, and the event record first.
-- --------------------------------------------------------------------------
SET @existing_event_id := (
  SELECT `id` 
  FROM `wp_lccl_de_fr_events` 
  WHERE `name` LIKE '%LCCL Annual Fundraiser Gala 2026%' OR `id` = 1 
  ORDER BY `id` ASC 
  LIMIT 1
);

DELETE FROM `wp_lccl_de_fr_bookings` 
WHERE `event_id` = 1 
   OR (`event_id` = @existing_event_id AND @existing_event_id IS NOT NULL)
   OR `id` BETWEEN 1 AND 112;

DELETE FROM `wp_lccl_de_fr_seat_blocks` 
WHERE `event_id` = 1 
   OR (`event_id` = @existing_event_id AND @existing_event_id IS NOT NULL);

DELETE FROM `wp_lccl_de_fr_tables` 
WHERE `event_id` = 1 
   OR (`event_id` = @existing_event_id AND @existing_event_id IS NOT NULL)
   OR `id` BETWEEN 169 AND 240;

DELETE FROM `wp_lccl_de_fr_table_types` 
WHERE `event_id` = 1 
   OR (`event_id` = @existing_event_id AND @existing_event_id IS NOT NULL)
   OR `id` IN (19, 20, 21, 22);

DELETE FROM `wp_lccl_de_fr_events` 
WHERE `id` = 1 
   OR (`id` = @existing_event_id AND @existing_event_id IS NOT NULL)
   OR `name` LIKE '%LCCL Annual Fundraiser Gala 2026%';

